        dr_lookup.setdefault(rn,set()).add((p['head'],p['tail']))
et_v=rv_v=dr_v=cf_v=0
total_r=total_e=0
parse_fail=0
dr_by_rel={}
with open('/root/schema_semantic_constrained_ie/outputs/w5_lora_scierc_full_s1_eval.jsonl') as f:
    for line in f:
        d=json.loads(line)
        p=d.get('parsed_output',{})
        if not p:
            parse_fail+=1
            continue
        ents=p.get('entities',[])
        rels=p.get('relations',[])
        total_e+=len(ents)
        total_r+=len(rels)
        ent_types={e['text']:e['type'] for e in ents}
        for e in ents:
            if e['type'] not in valid_et:
                et_v+=1
        for r in rels:
            if r['type'] not in valid_rt:
                rv_v+=1
                continue
            pair=(r.get('head_type',''),r.get('tail_type',''))
            rn=r['type']
            if rn in dr_lookup and pair not in dr_lookup[rn]:
                dr_v+=1
